class BuzzerManager {
private:
  uint32_t lastToggle = 0;
  uint16_t onDuration = 0, offDuration = 0;
  uint8_t remainingBeeps = 0;
  bool buzzerState = false;
public:
  void beep(uint8_t count, uint16_t onMs, uint16_t offMs) {
    remainingBeeps = count; onDuration = onMs; offDuration = offMs;
    buzzerState = true; lastToggle = millis();
    digitalWrite(BUZZER_PIN, HIGH);
  }
  void success() { beep(3, 100, 100); }
  void error()   { beep(1, 800, 0); }
  void warning() { beep(5, 50, 50); }
  void tick()    { beep(1, 50, 0); }
  void denied()  { beep(2, 200, 100); }

  void update() {
    if (remainingBeeps > 0) {
      uint32_t now = millis();
      if (buzzerState && now - lastToggle >= onDuration) {
        buzzerState = false; digitalWrite(BUZZER_PIN, LOW);
        lastToggle = now; remainingBeeps--;
      } else if (!buzzerState && remainingBeeps > 0 && now - lastToggle >= offDuration) {
        buzzerState = true; digitalWrite(BUZZER_PIN, HIGH);
        lastToggle = now;
      }
    } else { digitalWrite(BUZZER_PIN, LOW); }
  }
} buzzer;

