// MANAGER: TIME MANAGER
// ============================================================
uint32_t lastKnownUnixTime = 0;
uint32_t lastMillisReference = 0;

void updateTimeManager() {
  struct tm timeinfo;
  if (getLocalTime(&timeinfo, 0)) {
    if (timeinfo.tm_year > (2024 - 1900)) {
       sysHealth.timeState = TIME_SYNCED;
       time_t now; time(&now);
       lastKnownUnixTime = (uint32_t)now;
       lastMillisReference = millis();
    }
  } else if (sysHealth.timeState == TIME_SYNCED) {
    sysHealth.timeState = TIME_ESTIMATED;
  }
}

uint32_t getBestUnixTime(bool &isValid) {
  if (sysHealth.timeState == TIME_SYNCED || sysHealth.timeState == TIME_ESTIMATED) {
    isValid = true;
    return lastKnownUnixTime + ((millis() - lastMillisReference) / 1000);
  }
  isValid = false;
  return millis() / 1000;
}

