void enqueueSessionSync(const char* sessionJson) {
  enforceStorageRetention("/sync_queue.jsonl");
  File f = LittleFS.open("/sync_queue.jsonl", FILE_APPEND);
  if (f) { f.println(sessionJson); f.close(); }
}

void processSyncQueue() {
  if (WiFi.status() != WL_CONNECTED || coreState != CORE_IDLE) return;

  File q = LittleFS.open("/sync_queue.jsonl", FILE_READ);
  if (!q || q.size() == 0) {
    if (q) q.close();
    return;
  }

  currentOverlay = OVERLAY_SYNCING;
  bool allRecordsAcknowledged = true;

  char lineBuffer[256];
  size_t lineLen = 0;

  while (q.available()) {
    char c = q.read();
    if (c == '\n' || c == '\r') {
      if (lineLen > 0) {
        lineBuffer[lineLen] = '\0';
        bool ackReceived = api_uploadSessionRecord(lineBuffer);
        if (!ackReceived) {
          allRecordsAcknowledged = false;
        }
        lineLen = 0;
      }
    } else if (lineLen < sizeof(lineBuffer) - 1) {
      lineBuffer[lineLen++] = c;
    }
  }
  q.close();

  if (allRecordsAcknowledged) {
    LittleFS.remove("/sync_queue.jsonl");
    Serial.println("[SYNC] All queue items acknowledged by server. Local queue cleared.");
  } else {
    Serial.println("[SYNC] Queue preserved offline / waiting for Backend Server ACK.");
  }

  currentOverlay = OVERLAY_NONE;
}

