void readSensors() {
  sysHealth.freeHeap = ESP.getFreeHeap();
  sysHealth.wifiRssi = (WiFi.status() == WL_CONNECTED) ? WiFi.RSSI() : -100;

  env.temp = dht.readTemperature();
  env.hum = dht.readHumidity();
  env.valid = (!isnan(env.temp) && !isnan(env.hum));
  env.light = analogRead(LDR_PIN);
  env.aqRaw = analogRead(AQ_PIN);

  digitalWrite(TRIG_PIN, LOW); delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long dur = pulseIn(ECHO_PIN, HIGH, 30000);

  if (dur > 0) {
    integ.distanceCm = dur * 0.0343f / 2.0f;
    integ.presenceDetected = (integ.distanceCm <= DIST_PRESENCE_MAX);
    integ.proximityWarning = (integ.presenceDetected && integ.distanceCm < DIST_WARNING_MIN);
  } else {
    integ.distanceCm = -1.0f;
    integ.presenceDetected = false;
    integ.proximityWarning = false;
  }
}

void handleButtons() {
  uint32_t now = millis();

  if (digitalRead(START_PIN) == LOW && (now - lastStartBtn > DEBOUNCE_MS)) {
    lastStartBtn = now;
    if (coreState == CORE_IDLE || coreState == CORE_BREAK) {
      startSession(selectedPlanIndex);
    }
  }

  if (digitalRead(STOP_PIN) == LOW && (now - lastStopBtn > DEBOUNCE_MS)) {
    lastStopBtn = now;
    if (coreState == CORE_STUDYING) {
      if (currentSession.allowStop) {
        stopSession("USER_STOPPED");
      } else {
        currentOverlay = OVERLAY_DENIED;
        overlayClearMs = now + 2500;
        buzzer.denied();
        updateSystemLED();
      }
    }
  }
}

void sendTelemetry() {
  bool timeValid = false;
  uint32_t ts = getBestUnixTime(timeValid);
  char payload[256];
  snprintf(payload, sizeof(payload), "{\"dev\":\"%s\",\"st\":%d,\"ov\":%d,\"ts\":%lu,\"tv\":%s,\"heap\":%lu,\"env\":{\"t\":%.1f,\"h\":%.1f},\"dist\":%.1f}", deviceId, coreState, currentOverlay, ts, timeValid ? "true" : "false", sysHealth.freeHeap, env.valid ? env.temp : 0.0f, env.valid ? env.hum : 0.0f, integ.distanceCm
  );
  Serial.println(payload);
}

void handleDisplay() {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print(WiFi.status() == WL_CONNECTED ? "WIFI" : "OFF ");
  display.print(" | ");

  if (coreState == CORE_STUDYING) {
    uint32_t elapsed = (millis() - pomodoroStartMs) / 1000;
    uint32_t left = (currentSession.plannedDurationSec > elapsed) ? (currentSession.plannedDurationSec - elapsed) : 0;
    display.printf("%02lu:%02lu", left / 60, left % 60);
  } else if (coreState == CORE_BREAK) {
    uint32_t elapsed = (millis() - breakStartMs) / 1000;
    uint32_t left = (breakDurationSec > elapsed) ? (breakDurationSec - elapsed) : 0;
    display.printf("BRK %02lu:%02lu", left / 60, left % 60);
  } else {
    display.print("IDLE");
  }
  display.drawLine(0, 10, 128, 10, SSD1306_WHITE);

  if (currentOverlay == OVERLAY_ALERT) {
    display.setTextSize(2);
    display.setCursor(10, 30); display.print("TOO CLOSE!");
    display.setTextSize(1);
  } else if (currentOverlay == OVERLAY_DENIED) {
    display.setCursor(5, 25); display.print("STOP DENIED!");
    display.setCursor(5, 40); display.print("Controlled Task");
    display.setCursor(5, 52); display.print("In Progress...");
  } else if (currentOverlay == OVERLAY_SYNCING) {
    display.setCursor(10, 30); display.print("Syncing Data...");
  } else {
    bool pageEnv = (millis() / 4000) % 2 == 0;
    display.setCursor(0, 15);
    if (coreState == CORE_IDLE) {
      display.printf("Plan: %s\n", activePlans[selectedPlanIndex].title);
    }
    if (pageEnv) {
      display.printf("T:%.1fC H:%.0f%%\nL:%u AQ:%u\n", env.temp, env.hum, env.light, env.aqRaw);
    } else {
      display.printf("Dist: %.1f cm\nPres: %s\n", integ.distanceCm, integ.presenceDetected ? "YES" : "NO");
    }
  }
  display.display();
}

